/// <summary>
/// init method extension
/// </summary>
void init()
{
    METVendParameters metVendParameters = METVendParameters::find();

    next init();

    FormRun  fr = this as FormRun;

    FormControl rebateAccrualJournalName = fr.design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_RebateAccrualJournalName));
    FormControl holdInvoice = fr.design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_HoldInvoice));

    rebateAccrualJournalName.enabled(metVendParameters.VendorRebatesEnabled);
    holdInvoice.enabled(metVendParameters.VendorRebatesEnabled);
}
